<?php require_once __DIR__.'/_base.php'; $title='Complaints'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=post('status');$resp=post('admin_response');$pdo->prepare('UPDATE complaints SET status=?,admin_response=?,resolved_at=IF(? IN ("Resolved","Rejected"),NOW(),NULL) WHERE id=?')->execute([$status,$resp,$status,$id]);$c=$pdo->prepare('SELECT user_id FROM complaints WHERE id=?');$c->execute([$id]);$uid=$c->fetchColumn();notify($pdo,'Complaint update','Your complaint #'.$id.' is now '.$status.'.',$uid,null,'complaint');flash('success','Complaint updated.');redirect('complaints.php');}$st=$pdo->query('SELECT c.*,u.name user_name,p.name provider_name FROM complaints c JOIN users u ON u.id=c.user_id LEFT JOIN providers p ON p.id=c.provider_id ORDER BY c.created_at DESC');?><h2>Complaints</h2><div class="row g-3"><?php foreach($st->fetchAll() as $c):?><div class="col-lg-6"><div class="service-card p-4"><div class="d-flex justify-content-between"><h5><?=e($c['subject'])?></h5><?=badge($c['status'])?></div><p class="small text-secondary">By <?=e($c['user_name'])?> · <?=e($c['provider_name']??'General')?></p><p><?=e($c['description'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$c['id']?>"><select name="status" class="form-select mb-2"><option>Open</option><option>In Progress</option><option>Resolved</option><option>Rejected</option></select><textarea name="admin_response" class="form-control mb-2" placeholder="Admin response"><?=e($c['admin_response'])?></textarea><button class="btn btn-success">Update</button></form></div></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>